[
    {
        "path": "back-4-blood-trainer/back-4-blood-trainer.csproj",
        "content": "<Project Sdk=\"Microsoft.NET.Sdk\">\n  <PropertyGroup>\n    <OutputType>Exe</OutputType>\n    <TargetFramework>net8.0</TargetFramework>\n    <RootNamespace>Back4BloodTrainer</RootNamespace>\n    <ImplicitUsings>enable</ImplicitUsings>\n    <Nullable>enable</Nullable>\n  </PropertyGroup>\n\n  <ItemGroup>\n    <PackageReference Include=\"Memory.dll\" Version=\"0.6.0\" />\n  </ItemGroup>\n</Project>\n"
    },
    {
        "path": "back-4-blood-trainer/Program.cs",
        "content": "using Back4BloodTrainer.Core;\nusing Back4BloodTrainer.Trainer;\n\nnamespace Back4BloodTrainer;\n\n/// <summary>\n/// Entry point for the Back 4 Blood Trainer application.\n/// Provides a console-based interface for activating cheats.\n/// </summary>\ninternal class Program\n{\n    private static async Task Main(string[] args)\n    {\n        Console.WriteLine(\"=== Back 4 Blood Trainer v1.0 ===\");\n        Console.WriteLine(\"Make sure the game is running before using any features.\\n\");\n\n        // Initialize the game process manager\n        GameProcessManager processManager = new GameProcessManager();\n        if (!processManager.AttachToGame())\n        {\n            Console.WriteLine(\"Failed to attach to Back 4 Blood process. Exiting.\");\n            return;\n        }\n\n        // Initialize cheat modules\n        var healthCheat = new HealthCheat(processManager);\n        var ammoCheat = new AmmoCheat(processManager);\n        var speedCheat = new SpeedCheat(processManager);\n\n        Console.WriteLine(\"Available commands:\");\n        Console.WriteLine(\"  1 - Toggle Infinite Health\");\n        Console.WriteLine(\"  2 - Toggle Infinite Ammo\");\n        Console.WriteLine(\"  3 - Toggle Super Speed\");\n        Console.WriteLine(\"  q - Quit\");\n\n        bool running = true;\n        while (running && processManager.IsGameRunning())\n        {\n            Console.Write(\"\\nEnter command: \");\n            string? input = Console.ReadLine()?.Trim().ToLower();\n\n            switch (input)\n            {\n                case \"1\":\n                    healthCheat.Toggle();\n                    Console.WriteLine($\"Infinite Health: {(healthCheat.IsActive ? \"ON\" : \"OFF\")}\");\n                    break;\n                case \"2\":\n                    ammoCheat.Toggle();\n                    Console.WriteLine($\"Infinite Ammo: {(ammoCheat.IsActive ? \"ON\" : \"OFF\")}\");\n                    break;\n                case \"3\":\n                    speedCheat.Toggle();\n                    Console.WriteLine($\"Super Speed: {(speedCheat.IsActive ? \"ON\" : \"OFF\")}\");\n                    break;\n                case \"q\":\n                    running = false;\n                    break;\n                default:\n                    Console.WriteLine(\"Unknown command. Use 1, 2, 3, or q.\");\n                    break;\n            }\n\n            // Apply active cheats continuously\n            if (healthCheat.IsActive)\n                await healthCheat.Apply();\n            if (ammoCheat.IsActive)\n                await ammoCheat.Apply();\n            if (speedCheat.IsActive)\n                await speedCheat.Apply();\n        }\n\n        Console.WriteLine(\"Trainer exiting.\");\n    }\n}\n"
    },
    {
        "path": "back-4-blood-trainer/Core/GameProcessManager.cs",
        "content": "using System.Diagnostics;\nusing Memory;\n\nnamespace Back4BloodTrainer.Core;\n\n/// <summary>\n/// Manages attachment to the Back 4 Blood game process and provides memory access.\n/// </summary>\npublic class GameProcessManager\n{\n    private Process? _gameProcess;\n    private Mem? _memoryLib;\n    private const string ProcessName = \"Back4Blood\";\n\n    /// <summary>\n    /// Attempts to attach to the Back 4 Blood process.\n    /// </summary>\n    /// <returns>True if successfully attached, false otherwise.</returns>\n    public bool AttachToGame()\n    {\n        try\n        {\n            Process[] processes = Process.GetProcessesByName(ProcessName);\n            if (processes.Length == 0)\n            {\n                Console.WriteLine(\"Back 4 Blood is not running.\");\n                return false;\n            }\n\n            _gameProcess = processes[0];\n            _memoryLib = new Mem();\n            int pid = _gameProcess.Id;\n            bool opened = _memoryLib.OpenProcess(pid);\n\n            if (!opened)\n            {\n                Console.WriteLine(\"Failed to open process handle. Try running as administrator.\");\n                return false;\n            }\n\n            Console.WriteLine($\"Attached to Back 4 Blood (PID: {pid})\");\n            return true;\n        }\n        catch (Exception ex)\n        {\n            Console.WriteLine($\"Error attaching to process: {ex.Message}\");\n            return false;\n        }\n    }\n\n    /// <summary>\n    /// Reads a float value from the specified memory address.\n    /// </summary>\n    public float ReadFloat(IntPtr address)\n    {\n        if (_memoryLib == null) return 0f;\n        return _memoryLib.ReadFloat(address.ToString(\"X\"));\n    }\n\n    /// <summary>\n    /// Writes a float value to the specified memory address.\n    /// </summary>\n    public void WriteFloat(IntPtr address, float value)\n    {\n        if (_memoryLib == null) return;\n        _memoryLib.WriteMemory(address.ToString(\"X\"), \"float\", value.ToString());\n    }\n\n    /// <summary>\n    /// Reads an integer from the specified memory address.\n    /// </summary>\n    public int ReadInt(IntPtr address)\n    {\n        if (_memoryLib == null) return 0;\n        return _memoryLib.ReadInt(address.ToString(\"X\"));\n    }\n\n    /// <summary>\n    /// Writes an integer to the specified memory address.\n    /// </summary>\n    public void WriteInt(IntPtr address, int value)\n    {\n        if (_memoryLib == null) return;\n        _memoryLib.WriteMemory(address.ToString(\"X\"), \"int\", value.ToString());\n    }\n\n    /// <summary>\n    /// Checks if the game process is still running.\n    /// </summary>\n    public bool IsGameRunning()\n    {\n        if (_gameProcess == null) return false;\n        return !_gameProcess.HasExited;\n    }\n\n    /// <summary>\n    /// Gets the base address of the game module (useful for pointer chains).\n    /// </summary>\n    public IntPtr GetModuleBaseAddress(string moduleName = \"Back4Blood-Win64-Shipping.exe\")\n    {\n        if (_gameProcess == null) return IntPtr.Zero;\n        foreach (ProcessModule module in _gameProcess.Modules)\n        {\n            if (module.ModuleName == moduleName)\n                return module.BaseAddress;\n        }\n        return IntPtr.Zero;\n    }\n\n    /// <summary>\n    /// Cleanup resources.\n    /// </summary>\n    public void Dispose()\n    {\n        _memoryLib?.CloseProcess();\n        _gameProcess?.Dispose();\n    }\n}\n"
    },
