        "path": "back-4-blood-trainer/tests/TrainerTests.cs",
        "content": "using Back4BloodTrainer.Core;\nusing Back4BloodTrainer.Trainer;\n\nnamespace Back4BloodTrainer.Tests;\n\n/// <summary>\n/// Unit tests for the trainer modules.\n/// These tests use a mock process manager to simulate memory operations.\n/// </summary>\npublic class TrainerTests\n{\n    /// <summary>\n    /// Mock implementation of GameProcessManager for testing purposes.\n    /// </summary>\n    private class MockGameProcessManager : GameProcessManager\n    {\n        private readonly Dictionary<IntPtr, float> _floatMemory = new();\n        private readonly Dictionary<IntPtr, int> _intMemory = new();\n        private bool _isRunning = true;\n\n        public new bool AttachToGame() => true;\n\n        public new float ReadFloat(IntPtr address)\n        {\n            return _floatMemory.TryGetValue(address, out float value) ? value : 0f;\n        }\n\n        public new void WriteFloat(IntPtr address, float value)\n        {\n            _floatMemory[address] = value;\n        }\n\n        public new int ReadInt(IntPtr address)\n        {\n            return _intMemory.TryGetValue(address, out int value) ? value : 0;\n        }\n\n        public new void WriteInt(IntPtr address, int value)\n        {\n            _intMemory[address] = value;\n        }\n\n        public new bool IsGameRunning() => _isRunning;\n\n        public void StopGame() => _isRunning = false;\n\n        public new IntPtr GetModuleBaseAddress(string moduleName = \"Back4Blood-Win64-Shipping.exe\")\n        {\n            return new IntPtr(0x10000000); // Dummy base address\n        }\n    }\n\n    /// <summary>\n    /// Tests that the health cheat writes the expected value to memory.\n    /// </summary>\n    public static void TestHealthCheatAppliesValue()\n    {\n        var mockProcess = new MockGameProcessManager();\n        mockProcess.AttachToGame();\n        var healthCheat = new HealthCheat(mockProcess);\n\n        // Activate and apply\n        healthCheat.Toggle();\n        Task.Run(async () => await healthCheat.Apply()).GetAwaiter().GetResult();\n\n        // Check that memory was written (address is computed from base + offset)\n        IntPtr expectedAddr = mockProcess.GetModuleBaseAddress() + 0x12345678;\n        float writtenValue = mockProcess.ReadFloat(expectedAddr);\n        Console.WriteLine($\"Health value written: {writtenValue}\");\n        System.Diagnostics.Debug.Assert(writtenValue == 9999.0f, \"Health should be 9999.0f\");\n        Console.WriteLine(\"TestHealthCheatAppliesValue PASSED.\");\n    }\n\n    /// <summary>\n    /// Tests that the ammo cheat writes the expected value to memory.\n    /// </summary>\n    public static void TestAmmoCheatAppliesValue()\n    {\n        var mockProcess = new MockGameProcessManager();\n        mockProcess.AttachToGame();\n        var ammoCheat = new AmmoCheat(mockProcess);\n\n        ammoCheat.Toggle();\n        Task.Run(async () => await ammoCheat.Apply()).GetAwaiter().GetResult();\n\n        IntPtr expectedAddr = mockProcess.GetModuleBaseAddress() + 0x23456789;\n        int writtenValue = mockProcess.ReadInt(expectedAddr);\n        System.Diagnostics.Debug.Assert(writtenValue == 999, \"Ammo should be 999\");\n        Console.WriteLine(\"TestAmmoCheatAppliesValue
